select SUM(COALESCE(pi.taxable_total, sa.taxable_value, 0)) as purchase_taxable, SUM(COALESCE(gi.taxable_value, 0)) as gstr_taxable, SUM(COALESCE(pi.total_igst_amount,0)+COALESCE(pi.total_cgst_amount,0)+COALESCE(pi.total_sgst_amount,0) + COALESCE(sa.total_tax, 0)) as purchase_tax, SUM(COALESCE(gi.total_tax, 0)) as gstr_tax, SUM(COALESCE(pi.total_cgst_amount, sa.cgst, 0)) as purchase_cgst, SUM(COALESCE(pi.total_sgst_amount, sa.sgst, 0)) as purchase_sgst, SUM(COALESCE(pi.total_cess_amount, sa.cess, 0)) as purchase_cess, SUM(COALESCE(gi.cgst, 0)) as gstr_cgst, SUM(COALESCE(gi.sgst, 0)) as gstr_sgst, SUM(COALESCE(gi.cess, 0)) as gstr_cess from "reconciliation_results" as "rr" left join "reconciliation_runs" as "run" on "rr"."recon_run_id" = "run"."id" left join "normalized_gstr2a_invoices" as "gi" on "rr"."gstr2a_invoice_id" = "gi"."id" left join "purchase_vouchers" as "pi" on "rr"."purchase_invoice_id" = "pi"."id" left join "normalized_gstr2a_invoices" as "sa" on "rr"."gstr2a_source_id" = "sa"."id" where "rr"."workspace_id" = '8d84c307-e611-40c7-9d1d-3c04fce101fc' and "run"."run_type" in ('PURCHASE_2A', 'GSTR2A_VS_GSTR2B', 'PURCHASE_2A_VS_2B') limit 1;
